file.content:
    "total",
    "next_cursor",
)
LIST_AUDIT_REPORTS_DEFAULT_LIMIT = 50
LIST_AUDIT_REPORTS_MAX_LIMIT = 200

_audit_report_locks: dict[str, threading.RLock] = {}
_audit_report_locks_guard = threading.Lock()


class _AuditReportArchiveLock:
    """Same-archive mutex shared by threads and by separate processes.

    An in-process :class:`~threading.RLock` orders threads without touching
    the kernel; an exclusive ``flock`` on the ``<path>.lock`` sidecar orders
    processes against the same archive. Recorders and readers take the very
    same lock, so a query only ever observes a complete archive and two
    recorders cannot replace each other's generation. The kernel releases the
    flock automatically if a process dies while holding it.
    """

    def __init__(self, path: str, *, create: bool) -> None:
        self._path = path
        self._create = create
        key = os.path.abspath(path)
        with _audit_report_locks_guard:
            thread_lock = _audit_report_locks.get(key)
            if thread_lock is None:
                thread_lock = threading.RLock()
                _audit_report_locks[key] = thread_lock
        self._thread_lock = thread_lock
        self._handle = None

    def __enter__(self) -> "_AuditReportArchiveLock":
        self._thread_lock.acquire()
        directory = os.path.dirname(os.path.abspath(self._path)) or "."
        if not self._create and not os.path.isdir(directory):
            # Without a parent directory there cannot be an archive to read;
            # the strict loader below reports not_found without creating
            # anything.
            return self
        lock_path = self._path + ".lock"
        try:
            if self._create:
                os.makedirs(directory, exist_ok=True)
            handle = open(lock_path, "a+b")
        except FileNotFoundError as exc:
            self._thread_lock.release()
            category = ERR_IO if self._create else ERR_NOT_FOUND
            raise _CheckpointError(category) from exc
        except OSError as exc:
            self._thread_lock.release()
            raise _CheckpointError(ERR_IO) from exc
        try:
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        except OSError as exc:
            handle.close()
            self._thread_lock.release()
            raise _CheckpointError(ERR_IO) from exc
        self._handle = handle
        return self

    def __exit__(self, exc_type, exc, traceback) -> None:
        if self._handle is not None:
            try:
                fcntl.flock(self._handle.fileno(), fcntl.LOCK_UN)
            finally:
                self._handle.close()
        self._thread_lock.release()


def _audit_report_archive_hash(generation: int, reports: list) -> str:
    """SHA-256 over the canonical JSON bytes of every field but ``hash``."""
    body = {
        "v": AUDIT_REPORT_ARCHIVE_VERSION,
        "generation": generation,
        "reports": reports,
    }
    return hashlib.sha256(_canonical_json_bytes(body)).hexdigest()


def _validate_audit_report_archive(data: object) -> dict:
    """Strictly validate one version-1 audit-report archive.

    Exact key order ``v, generation, reports, hash``; the generation runs
    consecutively with the number of records (idempotent resubmissions do
    not grow either); reports keep their original recording order with no
    duplicate digest, and every stored report passes the same parse,
    digest/signature and evidence-replay checks as the offline verifier
    (checked against the public key sealed inside the report). The archive
    ``hash`` is recomputed last. Every defect is existing-state corruption.
    """
    if not isinstance(data, dict) or tuple(data.keys()) != (
        AUDIT_REPORT_ARCHIVE_KEYS
    ):
        raise _CheckpointError(ERR_STATE)
    if not _is_int(data["v"]) or data["v"] != AUDIT_REPORT_ARCHIVE_VERSION:
        raise _CheckpointError(ERR_STATE)
    generation = data["generation"]
    if not _is_int(generation) or generation < 1:
        raise _CheckpointError(ERR_STATE)
    raw_reports = data["reports"]
    if not isinstance(raw_reports, list) or not raw_reports:
        raise _CheckpointError(ERR_STATE)
    reports: list[dict] = []
    seen_digests: set[str] = set()
    for raw_report in raw_reports:
        try:
            parsed = _parse_state_anchors_audit_report(raw_report)
            pinned = (
                set(parsed["verified"])
                | set(parsed["missing"])
                | set(parsed["conflicts"])
            )
            _replay_state_anchors_audit_report(parsed, pinned, False)
            ordered = _canonical_state_anchors_audit_report(parsed)
        except _Failure as failure:
            raise _CheckpointError(ERR_STATE) from failure
        if parsed["digest"] in seen_digests:
            raise _CheckpointError(ERR_STATE)
        seen_digests.add(parsed["digest"])
        reports.append(ordered)
    if generation != len(reports):
        raise _CheckpointError(ERR_STATE)
    digest = data["hash"]
    if not crypto.is_hex64(digest):
        raise _CheckpointError(ERR_STATE)
    if _audit_report_archive_hash(generation, reports) != digest:
        raise _CheckpointError(ERR_STATE)
    return {
        "v": AUDIT_REPORT_ARCHIVE_VERSION,
        "generation": generation,
        "reports": reports,
        "hash": digest,
    }


def _load_audit_report_archive(path: str) -> dict | None:
    """Strictly load the audit-report archive at ``path``.

    Returns None when the archive is absent. An unreadable file is ``io``;
    bad UTF-8, malformed JSON and every shape/ordering/digest/replay defect
    is ``state``. The archive is never truncated or rebuilt by a read.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return None
    except UnicodeDecodeError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    except OSError as exc:
        raise _CheckpointError(ERR_IO) from exc
    try:
        data = json.loads(text)
    except ValueError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    return _validate_audit_report_archive(data)


def _atomic_write_audit_report_archive(path: str, archive: dict) -> None:
    """Write the archive in declared key order and atomically replace."""
    ordered = {key: archive[key] for key in AUDIT_REPORT_ARCHIVE_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def record_state_anchors_audit_report(
    path: object,
    report: object,
    expected_pairs: object,
    public_key: object,
) -> dict:
    """Record a fully re-verified signed audit report durably.

    ``report`` is a document produced by
    :func:`export_state_anchors_audit_report`, ``expected_pairs`` the
    recorder's pinned non-empty duplicate-free ``{"height", "account"}``
    list and ``public_key`` the pinned 64-lowercase-hex Ed25519 key. The
    report body digest, source evidence replay and grouping, the Ed25519
    seal and the pinned height/account coverage are all rechecked under the
    existing report rules before anything is written; the report public key
    must equal the pinned key.

    Reports are appended to the version-1 archive at ``path`` in their
    original recording order; the first report starts generation 1 and each
    genuinely new report takes the next consecutive generation, while the
    archive's current generation stays the total number of stored reports.
    Resubmitting a report with the same digest is idempotent: the file and
    report order hold, the stored report is left byte-identical and the
    result keeps the generation of the first recording, even after other
    reports have been appended. A same-digest submission with different
    content is ``integrity``.

    Success returns ``{"ok": True, "digest", "generation"}`` in that key
    order. Failure returns only ``{"ok": False, "error": category}``:
    ``input`` for bad parameters or report shape/type/hex/serialization,
    ``auth`` for a public-key mismatch, an unknown signature version or a
    failing Ed25519 seal, ``integrity`` for body-digest, evidence-replay,
    grouping or same-digest content conflicts, ``state`` for a corrupt
    existing archive (parse, digest, ordering or replay) and ``io`` for a
    read/write failure. Same-path calls are serialized across threads and
    across processes (an exclusive flock on the ``<path>.lock`` sidecar)
    and the write lands via a fsynced temp file and atomic replace; a crash
    only ever exposes the old archive or the complete new one. Nothing is
    raised and a failure never changes a file.
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    try:
        pairs = _validate_state_anchors_audit_pairs(expected_pairs)
        _stable_canonical_json_bytes(expected_pairs)
        _stable_canonical_json_bytes(report)
        if not isinstance(public_key, str) or not crypto.is_hex64(
            public_key
        ):
            raise _Failure(ERR_INPUT)
        parsed = _parse_state_anchors_audit_report(report)
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        return {"ok": False, "error": ERR_INPUT}

    if parsed["public_key"] != public_key:
        return {"ok": False, "error": ERR_AUTH}
    try:
        _replay_state_anchors_audit_report(parsed, set(pairs), True)
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        return {"ok": False, "error": ERR_INPUT}
    canonical_report = _canonical_state_anchors_audit_report(parsed)

    try:
        with _AuditReportArchiveLock(path, create=True):
            try:
                stored = _load_audit_report_archive(path)
            except _CheckpointError as failure:
                return {"ok": False, "error": failure.category}
            except Exception:
                return {"ok": False, "error": ERR_STATE}

            if stored is None:
                reports: list[dict] = []
                generation = 0
            else:
                reports = stored["reports"]
                generation = stored["generation"]

            for position, existing in enumerate(reports, start=1):
                if existing["digest"] != canonical_report["digest"]:
                    continue
                if existing != canonical_report:
                    return {"ok": False, "error": ERR_INTEGRITY}
                return {
                    "ok": True,
                    "digest": existing["digest"],
                    "generation": position,
                }

            reports.append(canonical_report)
            next_generation = generation + 1
            archive = {
                "v": AUDIT_REPORT_ARCHIVE_VERSION,
                "generation": next_generation,
                "reports": reports,
            }
            archive["hash"] = _audit_report_archive_hash(
                next_generation, reports
            )
            try:
                original = _read_bytes_or_none(path)
            except OSError:
                return {"ok": False, "error": ERR_IO}
            try:
                _atomic_write_audit_report_archive(path, archive)
            except (TypeError, ValueError):
                _restore_bytes(path, original)
                return {"ok": False, "error": ERR_INPUT}
            except OSError:
                _restore_bytes(path, original)
                return {"ok": False, "error": ERR_IO}

            return {
                "ok": True,
                "digest": canonical_report["digest"],
                "generation": next_generation,
            }
    except _CheckpointError as failure:
        return {"ok": False, "error": failure.category}


def read_state_anchors_audit_report(path: object, digest: object) -> dict:
    """Read one recorded audit report back by digest, restart-safe and read-only.

    ``path`` is the archive maintained by
    :func:`record_state_anchors_audit_report` and ``digest`` the report's
    64-lowercase-hex body digest. The call never writes, rewrites or cleans
    the archive. Success returns ``{"ok": True, "report", "generation"}`` in
    that key order with the original report document and the fixed
    generation it was first recorded at (its 1-based position in recording
    order), which never changes as further reports are appended.

    Failure returns only ``{"ok": False, "error": category}``: ``input`` for
    a bad path or digest, ``not_found`` for a missing archive or an unknown
    digest, ``state`` for archive parse/digest/ordering/replay corruption
    and ``io`` for a read failure. Same-path reads share the recorder's
    cross-process lock, so the report is always fetched from one complete
    archive; nothing is raised and identical file bytes yield identical
    results across restarts.
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    if not isinstance(digest, str) or not crypto.is_hex64(digest):
        return {"ok": False, "error": ERR_INPUT}

    try:
        with _AuditReportArchiveLock(path, create=False):
            try:
                stored = _load_audit_report_archive(path)
            except _CheckpointError as failure:
                return {"ok": False, "error": failure.category}
            except Exception:
                return {"ok": False, "error": ERR_STATE}
            if stored is None:
                return {"ok": False, "error": ERR_NOT_FOUND}
            for position, report in enumerate(stored["reports"], start=1):
                if report["digest"] == digest:
                    return {
                        "ok": True,
                        "report": copy.deepcopy(report),
                        "generation": position,
                    }
            return {"ok": False, "error": ERR_NOT_FOUND}
    except _CheckpointError as failure:
        return {"ok": False, "error": failure.category}


def list_state_anchors_audit_reports(
    path: object,
    public_key: object = None,
    limit: object = LIST_AUDIT_REPORTS_DEFAULT_LIMIT,
    cursor: object = 0,
) -> dict:
    """Page through the recorded audit reports, restart-safe and read-only.

    ``path`` is the archive maintained by
    :func:`record_state_anchors_audit_report`. ``public_key`` defaults to
    ``None`` (no filtering); otherwise it must be a 64-lowercase-hex
    Ed25519 key and only reports sealed by exactly that key are kept.
    ``limit`` defaults to 50 and must be a plain (non-boolean) integer in
    1..200; ``cursor`` defaults to 0 and must be a plain non-negative
    integer, the zero-based offset into the filtered matches. The call
    never writes, rewrites or cleans the archive and never advances its
    generation.

    Success returns ``{"ok": True, "generation", "items", "total",
    "next_cursor"}`` in that key order: ``generation`` is the archive's
    current total generation, ``total`` the number of filtered matches and
    ``items`` the requested page in ascending first-recorded generation
    (recording order — filtering never renumbers), each item
    ``{"generation", "report"}`` with the fixed 1-based recording position
    and the full report document, still acceptable to
    :func:`verify_state_anchors_audit_report`. A ``cursor`` equal to
    ``total`` yields an empty page; when further entries remain
    ``next_cursor`` is the current offset plus this page's size, otherwise
    it is None. A legal filter with no matches returns ``total`` 0, empty
    ``items`` and a None cursor.

    Failure returns only ``{"ok": False, "error": category}``: ``input``
    for a bad path, key, limit or cursor (including a ``cursor`` beyond
    ``total``), ``not_found`` for a missing archive, ``state`` for archive
    UTF-8/JSON/shape/digest/signature/evidence/grouping corruption — the
    whole archive is validated, so paging and filtering never mask a
    corrupt sibling report — and ``io`` for a read failure. Same-path
    reads share the recorder's cross-process lock, so the reports, count
    and total generation of one call all come from a single complete
    archive (the complete old or the complete new one under concurrent
    appends); nothing is raised and identical file bytes and arguments
    yield identical results across restarts.
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    if public_key is not None and (
        not isinstance(public_key, str) or not crypto.is_hex64(public_key)
    ):
        return {"ok": False, "error": ERR_INPUT}
    if not _is_int(limit) or not 1 <= limit <= LIST_AUDIT_REPORTS_MAX_LIMIT:
        return {"ok": False, "error": ERR_INPUT}
    if not _is_int(cursor) or cursor < 0:
        return {"ok": False, "error": ERR_INPUT}

    try:
        with _AuditReportArchiveLock(path, create=False):
            try:
                stored = _load_audit_report_archive(path)
            except _CheckpointError as failure:
                return {"ok": False, "error": failure.category}
            except Exception:
                return {"ok": False, "error": ERR_STATE}
            if stored is None:
                return {"ok": False, "error": ERR_NOT_FOUND}
            matches = [
                (position, report)
                for position, report in enumerate(
                    stored["reports"], start=1
                )
                if public_key is None or report["public_key"] == public_key
            ]
            total = len(matches)
            if cursor > total:
                return {"ok": False, "error": ERR_INPUT}
            page = matches[cursor : cursor + limit]
            items = [
                {"generation": position, "report": copy.deepcopy(report)}
                for position, report in page
            ]
            end = cursor + len(page)
            next_cursor = end if end < total else None
            return {
                "ok": True,
                "generation": stored["generation"],
                "items": items,
                "total": total,
                "next_cursor": next_cursor,
            }
    except _CheckpointError as failure:
        return {"ok": False, "error": failure.category}

    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return _public_hex(private_key)


def _public_hex(private_key: Ed25519PrivateKey) -> str:
    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


def sign_message(private_key_hex: str, message: bytes) -> str | None:
    """Sign ``message`` with an Ed25519 seed (64 hex chars); hex signature.

    Returns None for a malformed private key rather than raising.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return private_key.sign(message).hex()


def verify_signature(public_key_hex: str, message: bytes, signature_hex: str) -> bool:
    """Verify an Ed25519 signature (public key and signature are hex strings).

    Returns False for malformed hex or wrong key/signature lengths rather than
    raising, so callers can treat every verification failure uniformly.
    """
    try:
        public_bytes = bytes.fromhex(public_key_hex)
        signature_bytes = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    if len(public_bytes) != 32 or len(signature_bytes) != 64:
        return False
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature_bytes, message)
    except (InvalidSignature, ValueError):
        return False
    return True


# Merkle root of an empty transaction list; fixed so genesis blocks are identical.
EMPTY_MERKLE_ROOT = sha256_hex(b"")


def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


def verify_merkle_proof(
    tx_id: str,
    siblings: list[dict],
    merkle_root: str,
    block_hash: str,
    expected_block_hash: str,
) -> bool:
    """Verify a Merkle proof and bind it to a specific block hash.

    Re-hashes the leaf (``tx_id``) with the sibling path from leaf to root and
    compares the result with ``merkle_root``; ``block_hash`` must additionally
    equal ``expected_block_hash``. Every malformed input (non-64-char lowercase
    hex hash, illegal direction, non-list path, excessive depth) and every
    mismatch returns False rather than raising.
    """
    try:
        if not _is_hex64(tx_id):
            return False
        if not _is_hex64(merkle_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_block_hash):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        current = tx_id
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            if direction == "left":
                pair = sibling_hash + current
            elif direction == "right":
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))

        if not hmac.compare_digest(current, merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# Exact, ordered key sets of a batch Merkle-proof response document. They let
# verify_merkle_proof_bundle reject missing/extra keys *and* a wrong key order.
_BUNDLE_TOP_KEYS = ("height", "block_hash", "merkle_root", "transaction_ids", "proofs")
_BUNDLE_PROOF_KEYS = ("tx_id", "index", "siblings")
_BUNDLE_SIBLING_KEYS = ("direction", "hash")


def _exact_keys(value: object, keys: tuple[str, ...]) -> bool:
    """True iff ``value`` is a dict with exactly ``keys``, in that insertion order."""
    return isinstance(value, dict) and tuple(value.keys()) == keys


def verify_merkle_proof_bundle(
    bundle: object,
    expected_block_hash: object,
    expected_merkle_root: object,
) -> bool:
    """Strictly verify a batch Merkle-proof bundle offline.

    The bundle mirrors POST /v1/blocks/{height}/proofs::

